reverse_text_patch_pool.new:
.major-achievements{padding:68px 0;background:#e8efea;scroll-margin-top:24px}
.major-achievements .section-head{align-items:start}
.major-achievements .section-head h2{font-size:clamp(32px,4.5vw,50px)}
.major-achievement-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
.major-achievement-card{min-width:0;padding:28px;background:var(--white,#fffefa);border:1px solid #b7cbbd;border-top:4px solid #176e62;scroll-margin-top:24px}
.major-achievement-card h3{font-size:clamp(24px,2.6vw,31px);line-height:1.4;margin:0 0 16px}
.major-achievement-card h3 a{color:#135c55;text-decoration-thickness:1px;text-underline-offset:5px}
.major-achievement-card p{line-height:1.85}
.major-formula{font-size:clamp(16px,1.7vw,21px);line-height:1.9;overflow-wrap:anywhere;background:#edf3ee;padding:12px 14px}
.major-formula span{display:block}
.major-formula small{font-size:.8em}
.major-achievement-card .major-line{margin-top:20px;padding-top:12px;border-top:1px solid #d6ded6;font-size:.9rem}
.major-achievement-card details{font-size:.92rem}
.major-achievement-card .chen-feature{padding:12px 0 0}
.major-achievement-card .chen-feature>.wrap{width:100%}
.major-achievement-card .chen-feature-card{display:block;padding:0;border:0;background:transparent}
.major-achievement-card .chen-feature-identity{padding:14px;margin-top:16px}
.major-achievement-card .chen-feature-actions{gap:8px}
.major-achievement-card .chen-feature-actions a{padding:6px 10px}
.major-achievement-card h4{font-size:1rem;line-height:1.6}
.research-index-section .section-head h2{font-size:clamp(26px,3vw,36px)}
.research-index-section{padding-top:52px;padding-bottom:52px}
.primary-research-map{font-size:.9rem;color:#135c55;margin-top:16px}
@media(max-width:720px){.major-achievements{padding:45px 0}.major-achievement-grid{grid-template-columns:minmax(0,1fr);gap:18px}.major-achievement-card{padding:22px}}
